/**
 * One approved display string.
 *
 * `sheetId` is a row in the generated zh-TW JSON.
 * `enHash` is the sha256 of the Forge Steel English at the moment this row
 * was approved. `scripts/l10n/check.mjs` recomputes that English from
 * upstream data and fails when the hash no longer matches.
 *
 * `stripHeading` marks a rules row whose sheet text starts with a title line
 * and a blank line. Display drops those two lines. The export keeps them.
 */
export interface MappingEntry {
	sheetId: string;
	enHash: string;
	stripHeading?: true;
}

/**
 * Forge Steel display key → approved sheet row.
 *
 * Keys:
 *   element:<id>:<field>   for example element:ancestry-orc:name
 *                          Basic action names and ancestry ability names use
 *                          element:<ability id>:name. Sixteen action names
 *                          point at term.<slug>-action. Free Strike,
 *                          Opportunity Attack, and Claw Dirt reuse older rows.
 *                          Ancestry ability names are batch 8-1. Descriptions
 *                          and text sections stay for later batches.
 *   enum:<Enum>:<Member>   for example enum:Characteristic:Might
 *   data:<Class>:<field>   for example data:ConditionData:bleeding
 *   ui:<id>                for example ui:library.ancestries
 *   language:<English>     for example language:Caelian
 *                          Forge Steel languages have no id. The key is the
 *                          English name as stored. Kalliac is the orc preset
 *                          spelling of Kalliak.
 *   skill:<English>        for example skill:Alchemy
 *                          Forge Steel skills have no id. The key is the
 *                          English name as stored. Each skill has its own
 *                          Glossary row, term.<slug>-skill. Climb, Jump, Swim,
 *                          Culture, and Timescape do not reuse the older
 *                          movement, culture, or setting rows.
 *   section:<ability id>:<n>  for example section:charge:0
 *                          The nth text section of an ability.
 */
